#requires -Version 5.1
$ErrorActionPreference='Stop';$root='C:\Windows\Temp\Domenia-RC21-Completion';$out=Join-Path $root 'out';$started=[datetime]::UtcNow.ToString('o')
$cs=Get-CimInstance Win32_ComputerSystem;$os=Get-CimInstance Win32_OperatingSystem
$entry=[DirectoryServices.DirectoryEntry]::new('LDAP://localhost/RootDSE');$base=[string]$entry.Properties['defaultNamingContext'][0];$schema=[string]$entry.Properties['schemaNamingContext'][0];$entry.Dispose()
$searchRoot=[DirectoryServices.DirectoryEntry]::new('LDAP://localhost/'+$base);$search=[DirectoryServices.DirectorySearcher]::new($searchRoot);$search.Filter='(&(objectClass=computer)(sAMAccountName='+$env:COMPUTERNAME+'$))';[void]$search.PropertiesToLoad.Add('distinguishedName')
try{$found=$search.FindOne();if($null -eq $found){throw 'DC object not found'};$dn=[string]$found.Properties['distinguishedname'][0]}finally{$search.Dispose();$searchRoot.Dispose()}
[pscustomobject]@{Kind='Domenia.ScopedReadOnlyLab';Qualifying=$false;Environment=[pscustomobject]@{Domain=[string]$cs.Domain;Computer=$env:COMPUTERNAME;OS=[string]$os.Caption;OSVersion=[string]$os.Version;PowerShell=$PSVersionTable.PSVersion.ToString();Identity=[Security.Principal.WindowsIdentity]::GetCurrent().Name};Steps=@([pscustomobject]@{Id='ldap.rootdse-and-dc-object';Status='Passed';StartedUtc=$started;EndedUtc=[datetime]::UtcNow.ToString('o');BaseDn=$base;SchemaDn=$schema;ComputerDn=$dn});Scope='Read-only LDAP on the laboratory DC; no secrets or AD writes; does not qualify all LDAP operations or production'} | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $out 'LabLDAP.json') -Encoding UTF8
